    for(const z of [7,13,19,51,57,63]) for(const x of [1,9]) big(x,0,z,5,TWHEEL);        // two three-axle bogies
    big(3,6,22,10,V20,{s:[1,1],h:[1,1],r:1,x:1,g:2}); for(const [x,y,z] of v20Ext(3,6,22,0)) big(x,y,z,5,EXTB);
