    big(6,6,21,4,SEAT); big(5,6,85,5,E6);
    box(0,16,4,5,5,96,LG); for(const x of [0,15]) box(x,x+1,3,4,8,92,G);
    const prof=t=>({H:5+Math.round(14*Math.sqrt(Math.max(0,t))),hw:8*(0.5+0.5*Math.sqrt(Math.max(0,t)))});
