  if(k===(GUN.rsel[m]||0)&&n>1&&GM==='s'){ toast('ما عندك نوع ثاني من الذخيرة'); return; }
  GUN.rsel[m]=k; const nm=d0.rockets[k];
  if(GUN.mags[m]>0&&GUN.loaded[m]&&GUN.loaded[m]!==nm){ if(GM==='s') invAdd(MCI(GUN.loaded[m]),GUN.mags[m]); GUN.mags[m]=0; GUN.loaded[m]=null; gunReload(); }
