  const d=ram.d||.085; C_(.02,.02,.5,bm,.2); for(let i=0;i<4;i++){ const f=new THREE.Mesh(new THREE.BoxGeometry(.004,.05,.08),bm); f.rotation.z=i*Math.PI/2; f.position.set(Math.cos(i*Math.PI/2)*.03,Math.sin(i*Math.PI/2)*.03,.42); g.add(f); }
