    if(hitAt){ scene.remove(r.m); ROCKETS.splice(i,1); if(ram&&ram.grav&&r.t<.12){ fxSprite(hitAt.x,hitAt.y,hitAt.z,0x888888,.3,.6,{grow:2,op:.5}); clack(600,0,.3); continue; } explode(hitAt,r.type||'n'); continue; }
    r.p.addScaledVector(dir,step); r.m.position.copy(r.p); r.m.lookAt(r.p.clone().add(dir)); r.m.rotateY(Math.PI); if(r.spin) r.m.rotateZ(r.t*r.spin);
