  for(const [w,d,x,z] of [[1,.07,.5,.035],[1,.07,.5,.965],[.07,.86,.035,.5],[.07,.86,.965,.5]]){ const r=new THREE.Mesh(boxG(w,.025,d),[MM.haz,MM.haz,MM.haz,MM.base,MM.haz,MM.haz]); r.position.set(x,.0625,z); g.add(r); }
