      const gate=pd*.35; box('wall',[4,3],lx+.3,y0,lz+.3,t,wh,(pd-.6-gate)/2); box('wall',[4,3],lx+.3,y0,lz+.3+(pd-.6+gate)/2,t,wh,(pd-.6-gate)/2); box('wall',[4,3],lx+pw-.3-t,y0,lz+.3,t,wh,pd-.6);
