    for(const [a,b] of [[1,1],[1,-1],[-1,1],[-1,-1]]){ add(new THREE.CylinderGeometry(4.2,5,h+5,16),M,u+a*w/2,y0+(h+5)/2,v+b*d/2); col(u+a*w/2,y0,v+b*d/2,9,h+5,9); }
