      const order=[...HOT.keys()].filter(i=>HOT[i]&&HOT[i]!==REMOTE&&baseOf(HOT[i])===m).sort((a,b)=>(b===sel)-(a===sel));
      for(const i of order){ if(left<=0) break; const t=Math.min(left,S-h[i]); if(t>0){ h[i]+=t; left-=t; } }
