  { const cb=document.getElementById('charBox'); if(cb&&L.contains(cb)) document.getElementById('bagMe').appendChild(cb); }
  L.innerHTML=h;
  if(invMode){ const pl=L.querySelector('.mccPlayer'); if(pl) pl.appendChild($('#charBox')); }
  L.querySelectorAll('[data-arm]').forEach(b=>{ b.onmousedown=e=>{ e.preventDefault(); if(b.dataset.arm!=='1') return; const c=MCC.cur;
      if(c&&ARMOR[c.m]){ const old=SV.ar; SV.ar=c.m; invTake(c.m,0); MCC.cur=old?{m:old,n:1}:null; if(old) {} applyArmorVis(); }
      else if(!c&&SV.ar){ MCC.cur={m:SV.ar,n:1}; SV.ar=0; applyArmorVis(); } snd.click&&snd.click(); mccRender(); }; });
  // Minecraft drag: hold a stack, press on a square and sweep over others -> it is shared out (left: evenly, right: one each)
  L.querySelectorAll('[data-g],[data-be]').forEach(b=>{ b.addEventListener('mouseenter',()=>{ const D=MCC.drag; if(!D) return; const key=b.dataset.g!=null?'g'+b.dataset.g:null; if(!key||D.keys.includes(key)) return; const s=MCC.grid[+b.dataset.g]; if(s&&s.m!==D.m) return; if(D.keys.length>=D.n0&&D.btn===0) return; D.keys.push(key); b.classList.add('drg'); }); });
  L.querySelectorAll('[data-g],[data-bs],[data-h]').forEach(b=>{ b.addEventListener('mouseenter',()=>{ MCC.hover=b.dataset.g!=null?{t:'g',i:+b.dataset.g}:b.dataset.bs!=null?{t:'bs',i:+b.dataset.bs}:{t:'h',i:+b.dataset.h}; }); b.addEventListener('mouseleave',()=>{ MCC.hover=null; });
    b.addEventListener('dblclick',e=>{ e.preventDefault(); mccGather(); }); });
  L.querySelectorAll('[data-g]').forEach(b=>{ b.onmousedown=e=>{ e.preventDefault(); const gi=+b.dataset.g, c=MCC.cur, s=MCC.grid[gi];
      if(c&&(!s||s.m===c.m)&&!e.shiftKey){ MCC.drag={btn:e.button,m:c.m,n0:c.n,keys:['g'+gi],first:gi}; b.classList.add('drg'); return; }
      if(e.shiftKey&&MCC.grid[+b.dataset.g]&&!MCC.cur){ const s=MCC.grid[+b.dataset.g]; MCC.grid[+b.dataset.g]=null; mccGive(s.m,s.n); mccRender(); return; } mccSlot(+b.dataset.g,e.button===2); }; b.oncontextmenu=e=>e.preventDefault(); b.ontouchstart=e=>{ e.preventDefault(); mccSlot(+b.dataset.g,false); }; });
  L.querySelectorAll('[data-i]').forEach(b=>{ b.onmousedown=e=>{ e.preventDefault(); mccInvClick(+b.dataset.i,e.button===2); }; b.oncontextmenu=e=>e.preventDefault(); b.ontouchstart=e=>{ e.preventDefault(); mccInvClick(+b.dataset.i,false); }; });
  const on=(sel,f)=>L.querySelectorAll(sel).forEach(b=>{ b.onmousedown=e=>{ e.preventDefault(); f(b,e.button===2,e.shiftKey); }; b.oncontextmenu=e=>e.preventDefault(); b.ontouchstart=e=>{ e.preventDefault(); f(b,false,false); }; });
  on('[data-bs]',(b,r,sh)=>mccBagClick(MCC._bag[+b.dataset.bs],r,sh)); on('[data-be]',(b,r)=>mccBagDrop(r)); on('[data-h]',(b,r,sh)=>mccHotClick(+b.dataset.h,r,sh));
  const rb=L.querySelector('[data-r]'); rb.onmousedown=e=>{ e.preventDefault(); mccCraft(e.shiftKey); }; rb.oncontextmenu=e=>e.preventDefault(); rb.ontouchstart=e=>{ e.preventDefault(); mccCraft(false); };
  L.querySelector('.mccBookB').onclick=()=>{ MCC.book=!MCC.book; mccRender(); };
