hold($('#bDown'),()=>downHeld=true,()=>downHeld=false);
hold($('#bPlace'),()=>{ placeHeld=true; doPlace(); },()=>{ placeHeld=false; sweepLast=null; }); hold($('#bBreak'),breakPress,breakRelease); hold($('#bRide'),toggleRide);
