  const m=new Uint8Array(w*h); for(const [k,t] of P_.tiles){ const [tx,tz]=k.split(',').map(Number); for(let i=0;i<t.length;i++) if(t[i]){ const x=tx*PT+i%PT-x0, z=tz*PT+((i/PT)|0)-z0; m[z*w+x]=1; } }
