    if(ptrs.size===2){ const [a,b]=[...ptrs.values()], d=Math.hypot(a.x-b.x,a.y-b.y); if(pinch&&Math.abs(Math.log(d/pinch))>.35){ zoomMap(d>pinch?1:-1); pinch=d; } JM.cx-=dx/2/JM.ppm; JM.cz-=dy/2/JM.ppm; JM.follow=false; drawMap(); return; }
    clearTimeout(lpT);
