  if(id==='#pWorlds'||id==='#pNewW'||id==='#pConfirm'||id==='#pEvents'||id==='#pCred'){ const w=id==='#pWorlds'||id==='#pEvents'?Math.min(640,W-40):Math.min(480,W-40); return {stop:PCO[id],w,h:H,cx:W/2,cy:H/2}; }
