{ let last=performance.now(); const loop=()=>{ const n=performance.now(), dt=Math.min(.05,(n-last)/1000); last=n; try{ padTick(dt); }catch(e){} requestAnimationFrame(loop); }; requestAnimationFrame(loop); }
