// ================= DIFFICULTY (easy / normal / hard) and GRAPHICS PRESETS (low / medium / high / custom) =================
const DIFF={easy:{hurt:.5,zhp:.7,spawn:.55,n:'سهل'},normal:{hurt:1,zhp:1,spawn:1,n:'متوسط'},hard:{hurt:1.6,zhp:1.5,spawn:1.6,n:'صعب'}};
