{ const base=hurt; hurt=function(n,why,armorable){ return base.call(this,n*diffNow().hurt,why,armorable); }; }
{ const base=spawnZombie; spawnZombie=function(zt,x,y,z){ const m=base.apply(this,arguments); if(m){ m.hp=Math.round(m.hp*diffNow().zhp); m.hpMax=m.hp; } return m; }; }
{ const base=zombieSpawner; let acc=0; zombieSpawner=function(sim){ acc+=diffNow().spawn; let r; while(acc>=1){ acc-=1; r=base.call(this,sim); } return r; }; }
