// ================= HUMAN ENEMIES: mercenaries with AK-47, and an armored heavy with a machine gun =================
ZT.raider={n:'مرتزق',hp:18,spd:1.1,run:3.8,dmg:6,reach:1.3,h:1.85,s:1,see:48,w:0,human:1,gun:'AK-47',rpm:600,burst:[3,6],pause:[.7,1.5],mag:30,reload:2.6,acc:.5,range:[11,24]};
ZT.heavy={n:'المدرّع',hp:75,spd:.6,run:1.5,dmg:4,reach:1.5,h:2.3,s:1.25,see:50,w:0,human:1,gun:'PKM',rpm:650,burst:[8,16],pause:[1.2,2.4],mag:100,reload:5.5,acc:.3,range:[7,18],armor:.65,slam:1};
const HCAMO={raider:[0x6a6a44,0x55553a,0x7a7650,0x45452e],heavy:[0x4a5056,0x5a6066,0x3a4046,0x666c72]};
function hCamoTex(zt,seed){ const key='camo'+zt+seed; if(ZTEX[key]) return ZTEX[key]; const c=document.createElement('canvas'); c.width=c.height=16; const x=c.getContext('2d'), r=zRand(seed*31+7), pal=HCAMO[zt];
  for(let j=0;j<16;j++) for(let i=0;i<16;i++){ x.fillStyle='#'+pal[0].toString(16).padStart(6,'0'); x.fillRect(i,j,1,1); }
  for(let k=0;k<18;k++){ const col=pal[1+(r()*3|0)], i=r()*16|0, j=r()*16|0, w=1+(r()*3|0), h=1+(r()*2|0); x.fillStyle='#'+col.toString(16).padStart(6,'0'); x.fillRect(i,j,w,h); }
  const t=new THREE.CanvasTexture(c); t.magFilter=t.minFilter=THREE.NearestFilter; t.generateMipmaps=false; return ZTEX[key]=t; }
